    solution: "function chooseRendererMode({ hostIsImmutable = false, isTestEnvironment = false } = {}) {\n  if (isTestEnvironment) return \"no-op\";\n  if (hostIsImmutable) return \"persistence\";\n  return \"mutation\";\n}\n",
